  java.longToast('\n暂未开放：' + parsed.type + '\n当前支持小说 / 漫画（c:）（可用 g: 共享）')
  getApiUrl('/novel/search', { keyword: '0', page: 1, share: true })
} else {
  var apiType = parsed.mode === 'comic' ? 'comic' : 'novel'
  var params = {
    keyword: parsed.keyword || key,
    page: page,
  }
  if (parsed.share) params.share = true
  try {
    var rank = String(source.get('searchRank') || '').trim()
    if (rank === '0' || rank === '1' || rank === '2' || rank === '3') {
      params.rankType = rank
    }
  } catch (e2) { }
  getApiUrl('/' + apiType + '/search', params)
}
